def main():
    out=ROOT/'B141_B145_meanings_andindependent_drafts_v1.json'
    assert not out.exists()
    packet_path=ROOT/'clean_source_packet.json';choices_path=ROOT/'clean_choice_objects.json'
    packet,choices=map(load,[packet_path,choices_path]);rows=[]
    for group in packet['groups']:
        b=group['block']
        if b not in DATA:continue
        assert {int(r['id'].split('_R')[-1]) for r in group['records']}==set(DATA[b]),b
        for original in group['records']:
            assert original['source_decode_error'] is None
            index=int(original['id'].split('_R')[-1]);meaning,draft=DATA[b][index]
            row=deepcopy(original)
            row.update(source_meaning=meaning,independent_English=draft,context=CONTEXT[b],
                speaker='Native source selector '+str(row['source_selector'])+'; final name/role binding pending',
                review=dict(source=False,context=False,localization=False,naturalness=False,formatting=False),
                current_English_comparison_pending=True,approved_names_terms_titles_andruntime_substitutions_pending=True,new_credit=0)
            assert '\n' not in draft and not any(x in draft for x in ['{LB','{ALIGN','{PAD}'])
            rows.append(row)
    for original in choices['records']:
        if original['block']!=143:continue
        row=deepcopy(original)
        row.update(source_meaning='Request clarification ofthe offered lesson.' if row['source_index']==0 else 'Say that the method is already understood.',
            independent_English='What do you mean?' if row['source_index']==0 else 'I understand.',context=CONTEXT[143],speaker='Player choice',
            review=dict(source=False,context=False,localization=False,naturalness=False,formatting=False),
            current_English_comparison_pending=True,complete_native_menu_binding_andformatting_pending=True,new_credit=0)
        rows.append(row)
    assert len(rows)==191 and len({r['id'] for r in rows})==191
    save(out,dict(records=rows,records_count=191,ordinary_speeches=189,typed_captions=2,
        complete_blocks=[141,142,143,144,145],source_contexts=CONTEXT,
        provisional_identity_terms_titles=['Eirene','Commander ascompany-leader address','ship ofthe line type label',
            'Crimson Pigment','Old Parchment','Mysterious Tablet upper/lower halves','adjutant/diplomatic-document/hostile-status UI labels'],
        distinct_native_FU_substitution_not_qualified_or_replaced_by_FI=True,
        all_five_gates_pending=True,no_current_English_extracted_for_this_intake_before_drafts=True,
        no_blanket_claim_of_historical_unexposure=True,no_ROM_or_registry_changes=True,new_credit=0,guide_photos=False,
        evidence={str(p):sha(p.read_bytes()) for p in [packet_path,choices_path,Path(__file__)]}))
    print('Sealed191 clean meanings/independent drafts acrossfive completeblocks,including84-speech combat/investment tutorial. Current comparison,bindings andall five gates pending;no credit.')


if __name__=='__main__':main()
